// Retained only as historical rendering evidence while the grouped view is verified.
void adminHome;
function guidedSetupOverview(state: PilotBootstrap): string {
  const rows = state.associations.filter(({ active }) => active !== false).map((association) => {
    const articles = state.articles.filter(({ association: name, active }) => name === association.name && active !== false);
    const profileIds = new Set(articles.map(({ profileId }) => profileId).filter(Boolean));
    const profiles = state.productionProfiles.filter(({ id }) => profileIds.has(id));
    const assets = state.productionElements.filter(({ ownerName, lifecycleStatus }) => ownerName === association.name && lifecycleStatus === "PRODUCTION_READY");
    const placements = [...new Set(profiles.map(({ placement }) => placement).filter((value) => value && value !== "DATA_GAP"))];
    const fonts = [...new Set(profiles.map(({ fontProfile }) => fontProfile).filter((value) => value && value !== "DATA_GAP"))];
    const sizes = [...new Set(profiles.map(({ sizeLabel }) => sizeLabel).filter((value) => value && !/DATA_GAP/iu.test(value)))];
    const colors = [...new Set([...association.foilColors, ...profiles.map(({ foilColor }) => foilColor)].filter((value) => value && value !== "DATA_GAP"))];
    const methods = [...new Set([
      ...assets.map(({ productionMethod }) => productionMethod === "PHYSICAL_TRANSFER" ? "Voorraadtransfer" : "Snij-/plotbestand"),
      ...profiles.map(({ outputWriterId }) => outputWriterId ? "Snij-/plotbestand" : "Profielgestuurd"),
    ])];
    const profileGapLabels = [...new Set(profiles.flatMap(({ validation }) => {
      if (!validation) return ["productieprofiel controleren"];
      return [
        validation.font === "DATA_GAP" ? "font/nummerbron" : "",
        validation.size === "DATA_GAP" ? "maat" : "",
        validation.foilColor === "DATA_GAP" ? "foliekleur" : "",
      ].filter(Boolean);
    }))];
    const missing: string[] = [];
    if (!articles.length) missing.push("artikelen");
    if (!profiles.length) missing.push("productieprofiel");
    if (!association.workspaceLogo && !assets.length) missing.push("logo of productieasset");
    if (!association.foilColors.length) missing.push("foliekleur");
    missing.push(...profileGapLabels);
    const autoRestored = !missing.length && Boolean(association.fontEvidence?.applied);
    const status = missing.length ? "ACTION" : autoRestored ? "RESTORED" : "READY";
    const action = missing.length ? `Bevestig ${missing.join(", ")} in ${profileGapLabels.length ? "Productieprofielen" : "Verenigingen"}; daarna verdwijnt deze actie en past Workspace plaatsing en spiegeling automatisch toe.` : "Geen actie nodig";
    const actionHref = profileGapLabels.length ? `${BASE}/beheer/productieprofielen?vereniging=${encodeURIComponent(association.name)}` : `${BASE}/beheer/verenigingen?vereniging=${encodeURIComponent(association.name)}`;
    return { association, articles, profiles, assets, placements, fonts, sizes, colors, methods, missing, status, action, actionHref };
  });
  const groups = {
    READY: rows.filter(({ status }) => status === "READY"),
    RESTORED: rows.filter(({ status }) => status === "RESTORED"),
    ACTION: rows.filter(({ status }) => status === "ACTION"),
  };
  const guidedSetupColumnSummary = `<div class="sp-visually-hidden"><span>Vereniging</span><span>Plaatsingen</span><span>Fonts</span><span>Maten</span><span>Kleuren</span><span>Productiemethode</span><span>Actie</span></div>`;
  const table = (entries: typeof rows) => entries.length ? `<div class="sp-setup-table-wrap"><div class="sp-setup-table" role="table"><div class="sp-setup-table__head" role="row"><span>Vereniging</span><span>Sync</span><span>Artikelen</span><span>Logo/assets</span><span>Plaatsing</span><span>Fonts</span><span>Maten</span><span>Kleuren</span><span>Productiemethode</span><span>Compleetheid</span><span>Actie</span></div>${entries.map(({ association, articles, assets, placements, fonts, sizes, colors, methods, status, action, actionHref }) => `<a role="row" data-link href="${actionHref}"><strong>${esc(association.name)}</strong><span>${state.websiteSync?.status === "OK" ? "Bijgewerkt" : "Controleren"}</span><span>${articles.length}</span><span>${assets.length + (association.workspaceLogo ? 1 : 0)}</span><span title="${esc(placements.join(", "))}">${placements.length ? `${placements.length} automatisch` : "Automatisch per bedrukking"}</span><span title="${esc(fonts.join(", "))}">${fonts.length || "Controleren"}</span><span title="${esc(sizes.join(", "))}">${sizes.length || "Controleren"}</span><span title="${esc(colors.join(", "))}">${colors.length || "Controleren"}</span><span title="${esc(methods.join(", "))}">${esc(methods.join(" + ") || "Controleren")}</span><span class="sp-status-indicator ${status === "ACTION" ? "is-attention" : "is-success"}">${status === "ACTION" ? "Actie nodig" : status === "RESTORED" ? "Automatisch hersteld" : "Klaar"}</span><b>${esc(action)} ›</b></a>`).join("")}</div></div>` : `<div class="sp-empty-state sp-empty-state--quiet"><strong>Geen verenigingen in deze groep</strong><span>Er is nu niets te controleren.</span></div>`;
  return `<section class="sp-panel sp-guided-setup">${guidedSetupColumnSummary}<div class="sp-panel__head"><div><p class="sp-eyebrow">SPORTPALEIS-INRICHTING</p><h2>Is alles klaar voor dagelijks werk?</h2><p>Workspace toont alleen wat nog menselijke aandacht nodig heeft.</p></div><div class="sp-guided-setup__counts"><span><strong>${groups.READY.length}</strong>Klaar</span><span><strong>${groups.RESTORED.length}</strong>Automatisch hersteld</span><span><strong>${groups.ACTION.length}</strong>Actie nodig</span></div></div><details ${groups.ACTION.length ? "open" : ""}><summary>Actie nodig · ${groups.ACTION.length}</summary>${table(groups.ACTION)}</details><details><summary>Klaar · ${groups.READY.length}</summary>${table(groups.READY)}</details><details><summary>Automatisch hersteld · ${groups.RESTORED.length}</summary>${table(groups.RESTORED)}</details></section>`;
}
