  const objectCount = lines.reduce((sum, { line }) => sum + line.quantity, 0); const preMirrored = state.productionJobs.some(({ snapshot, humanAcceptance }) => snapshot.artifact.version.includes("AUTO-MIRROR-AB") && humanAcceptance.status === "PASS");
