  return `<a class="sp-back" data-link href="${BASE}/beheer">← Beheer</a><nav class="sp-people-tabs" aria-label="Mensenbeheer"><a data-link href="${BASE}/beheer/gebruikers">Gebruikers</a><a class="is-active" data-link href="${BASE}/beheer/werknemers">Medewerkers & verkoopnummers</a><a data-link href="${BASE}/beheer/rollen">Rollen & werkplekken</a></nav>${head("MEDEWERKERS & ROLLEN", "Medewerkers en verkoopnummers", "Verkoopnummer is operationele attributie en geen login-identiteit.")}<section class="sp-panel sp-employee-summary"><div class="sp-production-summary"><div><strong>${employees.length}</strong><span>codes</span></div><div><strong>${humanCount}</strong><span>medewerkers</span></div><div><strong>${source?.unverified ?? 0}</strong><span>onbevestigd</span></div></div><label class="sp-search"><span class="sp-visually-hidden">Zoek medewerker</span><input type="search" data-employee-search placeholder="Naam of verkoopnummer"></label>${source ? `<p class="sp-muted">Aangeleverde bron vergeleken: ${source.matched} bestaand behouden, ${source.added} veilig toegevoegd. Onbekende lege codes zijn niet als werknemer aangemaakt.</p>` : ""}</section><section class="sp-employee-list">${employees.map((employee) => `<details class="sp-panel sp-employee-record" data-employee-row="${esc(`${employee.name} ${employee.salesNumber}`.toLocaleLowerCase("nl-NL"))}"><summary><strong>${esc(employee.name)}</strong><span>Verkoopnummer ${esc(employee.salesNumber)} · ${employee.active ? "Actief" : "Inactief"} · ${employee.accountType === "SYSTEM" ? "Systeemcode" : employee.accountType === "FUNCTION" ? "Functiecode" : "Medewerker"}</span></summary>${fields(employee)}</details>`).join("") || `<div class="sp-panel"><p>Nog geen werknemers.</p></div>`}</section><details class="sp-panel sp-employee-add"><summary>Medewerker of operationele code toevoegen</summary>${fields()}</details>`;
